package verification

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

// consentTextHashGoldenPath is the path from sdk/verification-go/ to the
// consent text hash golden vector file. Generated by
// cmd/gen-consent-hash-vectors.
// A copy of sdk/testdata/consent_text_hash_golden.json, kept inside the module so its tests pass
// outside the monorepo; scripts/publish-sdks.sh refuses a copy that differs.
const consentTextHashGoldenPath = "testdata/shared/consent_text_hash_golden.json"

type consentTextHashVector struct {
	Name          string `json:"name"`
	Description   string `json:"description"`
	InputBytesHex string `json:"input_bytes_hex"`
	TemplateHash  string `json:"template_hash"`
	RenderedHash  string `json:"rendered_hash"`
}

type consentTextHashGoldenFile struct {
	Version               int                     `json:"version"`
	Notice                string                  `json:"notice"`
	RenderedHashPepperHex string                  `json:"rendered_hash_pepper_hex"`
	Vectors               []consentTextHashVector `json:"vectors"`
}

func loadConsentTextHashGolden(t *testing.T) consentTextHashGoldenFile {
	t.Helper()
	raw, err := os.ReadFile(consentTextHashGoldenPath)
	if err != nil {
		t.Fatalf("read golden file %q: %v", consentTextHashGoldenPath, err)
	}
	var g consentTextHashGoldenFile
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("parse golden file: %v", err)
	}
	if g.Version != 2 {
		t.Fatalf("unsupported golden file version: %d", g.Version)
	}
	if len(g.Vectors) < 3 {
		t.Fatalf("expected >= 3 vectors, got %d", len(g.Vectors))
	}
	if g.RenderedHashPepperHex == "" {
		t.Fatal("golden file missing rendered_hash_pepper_hex")
	}
	return g
}

// renderedHashTestPepper decodes the golden file's committed synthetic
// pepper into raw bytes for HashRendered calls.
func renderedHashTestPepper(t *testing.T, g consentTextHashGoldenFile) []byte {
	t.Helper()
	p, err := hex.DecodeString(g.RenderedHashPepperHex)
	if err != nil {
		t.Fatalf("decode rendered_hash_pepper_hex: %v", err)
	}
	return p
}

// TestHashTemplate_GoldenVectors asserts the Go SDK HashTemplate output
// byte-matches every committed vector in consent_text_hash_golden.json.
func TestHashTemplate_GoldenVectors(t *testing.T) {
	g := loadConsentTextHashGolden(t)
	for _, v := range g.Vectors {
		t.Run(v.Name, func(t *testing.T) {
			in, err := hex.DecodeString(v.InputBytesHex)
			if err != nil {
				t.Fatalf("decode input hex: %v", err)
			}
			got := HashTemplate(in)
			if got != v.TemplateHash {
				t.Errorf("HashTemplate mismatch\n got:  %s\n want: %s", got, v.TemplateHash)
			}
		})
	}
}

// TestHashRendered_GoldenVectors asserts the Go SDK HashRendered output
// byte-matches every committed vector in consent_text_hash_golden.json.
func TestHashRendered_GoldenVectors(t *testing.T) {
	g := loadConsentTextHashGolden(t)
	pepper := renderedHashTestPepper(t, g)
	for _, v := range g.Vectors {
		t.Run(v.Name, func(t *testing.T) {
			in, err := hex.DecodeString(v.InputBytesHex)
			if err != nil {
				t.Fatalf("decode input hex: %v", err)
			}
			got := HashRendered(in, pepper)
			if got != v.RenderedHash {
				t.Errorf("HashRendered mismatch\n got:  %s\n want: %s", got, v.RenderedHash)
			}
		})
	}
}

// TestHashRendered_WrongPepperMismatches pins the security property the
// whole epic exists to restore: a caller without the tenant's actual
// revealed pepper cannot reproduce the server's stored consent_rendered_hash,
// even with the exact plaintext bytes.
func TestHashRendered_WrongPepperMismatches(t *testing.T) {
	g := loadConsentTextHashGolden(t)
	wrongPepper := make([]byte, 64)
	for i := range wrongPepper {
		wrongPepper[i] = 0xff
	}
	for _, v := range g.Vectors {
		t.Run(v.Name, func(t *testing.T) {
			in, err := hex.DecodeString(v.InputBytesHex)
			if err != nil {
				t.Fatalf("decode input hex: %v", err)
			}
			if got := HashRendered(in, wrongPepper); got == v.RenderedHash {
				t.Error("HashRendered matched golden output with the WRONG pepper")
			}
		})
	}
}

// TestHashTemplate_NotEqualToHashRendered asserts the two helpers produce
// different output for the same input. Locks the 18_20 review B4
// domain-separation invariant at the SDK layer.
func TestHashTemplate_NotEqualToHashRendered(t *testing.T) {
	pepper := renderedHashTestPepper(t, loadConsentTextHashGolden(t))
	inputs := [][]byte{
		[]byte(""),
		[]byte("hello"),
		[]byte("I consent to pii_inspection processing.\n"),
	}
	for _, in := range inputs {
		if HashTemplate(in) == HashRendered(in, pepper) {
			t.Errorf("HashTemplate == HashRendered for input %q — domain separation broken", in)
		}
	}
}

// TestHashTemplate_OutputShape asserts output is exactly 128 lowercase hex
// characters for any input. A sibling regression guard that does not depend
// on the golden file.
func TestHashTemplate_OutputShape(t *testing.T) {
	pepper := renderedHashTestPepper(t, loadConsentTextHashGolden(t))
	for _, in := range [][]byte{nil, {}, []byte("x"), []byte("longer payload bytes")} {
		for _, got := range []string{HashTemplate(in), HashRendered(in, pepper)} {
			if len(got) != 128 {
				t.Errorf("expected 128 hex chars, got %d (%q)", len(got), got)
			}
			for _, c := range got {
				if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
					t.Errorf("non-lowercase-hex char in output: %q", got)
					break
				}
			}
		}
	}
}
